using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Text.Json.Nodes;using System.Windows;using System.Windows.Controls;using System.Windows.Media;
namespace BF4Launcher;
public sealed class ProfileLevelWindow:Window {
 public long Experience{get;private set;}public ProfileLevelWindow(string name,JsonNode player,JsonArray scores){Title="修改等级 / 经验 · "+name;Width=540;Height=340;WindowStartupLocation=WindowStartupLocation.CenterOwner;Foreground=Bf4Theme.Text;Background=new SolidColorBrush(Color.FromRgb(10,25,35));var p=new StackPanel{Margin=new Thickness(25)};Content=p;p.Children.Add(new TextBlock{Text="只修改等级及累计经验，保存前自动备份。",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,18)});p.Children.Add(new TextBlock{Text="等级（0～140）"});var rank=new TextBox{Text=player["rank"]?.ToString()??"0",Margin=new Thickness(0,6,0,14)};p.Children.Add(rank);p.Children.Add(new TextBlock{Text="累计经验（也可直接输入）"});var xp=new TextBox{Text=player["experience"]?.ToString()??"0",Margin=new Thickness(0,6,0,16)};p.Children.Add(xp);bool syncing=false;rank.TextChanged+=(s,e)=>{if(syncing)return;if(int.TryParse(rank.Text,out int n)&&n>=0&&n<scores.Count){syncing=true;xp.Text=scores[n]!.ToString();syncing=false;}};xp.TextChanged+=(s,e)=>{if(syncing||!long.TryParse(xp.Text,out long value)||value<0)return;int level=0;for(int i=0;i<scores.Count;i++)if(long.TryParse(scores[i]?.ToString(),out long threshold)&&value>=threshold)level=i;syncing=true;rank.Text=level.ToString();syncing=false;};var row=new WrapPanel();var save=new Button{Content="备份并保存"};save.Click+=(s,e)=>{if(!int.TryParse(rank.Text,out int enteredRank)||enteredRank<0||enteredRank>=scores.Count){MessageBox.Show(this,"等级须为0～140的整数。");return;}if(!long.TryParse(xp.Text,NumberStyles.Integer,CultureInfo.InvariantCulture,out var n)||n<0||n>2147483647){MessageBox.Show(this,"经验值须为0～2147483647的整数。");return;}Experience=n;DialogResult=true;};row.Children.Add(save);var cancel=new Button{Content="取消"};cancel.Click+=(s,e)=>Close();row.Children.Add(cancel);p.Children.Add(row);}
}
public sealed class LoadoutWindow:Window {
 public JsonNode Policy{get;private set;}=new JsonObject();public bool Unarmed{get;private set;}public bool Restart{get;private set;}readonly Dictionary<string,CheckBox> boxes=new();readonly List<Expander> groups=new();readonly TextBlock status=new();
 public LoadoutWindow(JsonNode snapshot){Title="人机装备限制";Width=840;Height=720;MinWidth=650;MinHeight=500;WindowStartupLocation=WindowStartupLocation.CenterOwner;Foreground=Bf4Theme.Text;Background=new SolidColorBrush(Color.FromRgb(10,25,35));Unarmed=snapshot["policy"]?["unarmed"]?.GetValue<bool>()==true;var selected=(snapshot["policy"]?["weaponIds"]?.AsArray()??new JsonArray()).Select(x=>x!.ToString()).ToHashSet();var grid=new Grid{Margin=new Thickness(24)};grid.RowDefinitions.Add(new(){Height=GridLength.Auto});grid.RowDefinitions.Add(new());grid.RowDefinitions.Add(new(){Height=GridLength.Auto});Content=grid;var top=new StackPanel();grid.Children.Add(top);top.Children.Add(new TextBlock{Text="勾选即禁止人机使用，真人装备不受影响。",Margin=new Thickness(0,0,0,10)});var search=new TextBox{ToolTip="搜索装备名称",Margin=new Thickness(0,0,0,10)};top.Children.Add(search);var presets=new WrapPanel();top.Children.Add(presets);var clear=new Button{Content="取消全部禁用"};clear.Click+=(s,e)=>{Unarmed=false;foreach(var b in boxes.Values){b.IsEnabled=true;b.IsChecked=false;}UpdateStatus();};presets.Children.Add(clear);
  var list=new StackPanel();var scroll=new ScrollViewer{Content=list,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(scroll,1);grid.Children.Add(scroll);
  foreach(var group in snapshot["weaponGroups"]!.AsArray()){var content=new WrapPanel();var expander=new Expander{Header=group!["label"]!.ToString(),Content=content,IsExpanded=true,Margin=new Thickness(0,6,0,10)};groups.Add(expander);list.Children.Add(expander);foreach(var item in group["items"]!.AsArray()){var id=item!["id"]!.ToString();var cb=new CheckBox{Content=item["label"]!.ToString(),Tag=id,IsChecked=selected.Contains(id),IsEnabled=!Unarmed,MinWidth=175,Margin=new Thickness(0,4,8,4)};cb.Click+=(s,e)=>UpdateStatus();boxes[id]=cb;content.Children.Add(cb);}}
  foreach(var preset in snapshot["weaponPresets"]?.AsArray()??new JsonArray()){var pr=preset!;var button=new Button{Content=pr["label"]!.ToString(),ToolTip=pr["description"]?.ToString()};button.Click+=(s,e)=>{bool wasUnarmed=Unarmed;Unarmed=pr["unarmed"]?.GetValue<bool>()==true;if(wasUnarmed)foreach(var b in boxes.Values)b.IsChecked=false;foreach(var id in pr["weaponIds"]!.AsArray().Select(x=>x!.ToString()))if(boxes.TryGetValue(id,out var b))b.IsChecked=true;foreach(var b in boxes.Values)b.IsEnabled=!Unarmed;UpdateStatus();};presets.Children.Add(button);}
  search.TextChanged+=(s,e)=>{string q=search.Text.Trim();foreach(var ex in groups){var panel=(WrapPanel)ex.Content;foreach(CheckBox b in panel.Children)b.Visibility=b.Content!.ToString()!.Contains(q,StringComparison.OrdinalIgnoreCase)?Visibility.Visible:Visibility.Collapsed;ex.Visibility=panel.Children.Cast<CheckBox>().Any(b=>b.Visibility==Visibility.Visible)?Visibility.Visible:Visibility.Collapsed;}};
  var bottom=new StackPanel{Margin=new Thickness(0,10,0,0)};Grid.SetRow(bottom,2);grid.Children.Add(bottom);bottom.Children.Add(status);var buttons=new WrapPanel();bottom.Children.Add(buttons);foreach(bool restart in new[]{false,true}){var value=restart;var b=new Button{Content=value?"保存并重启游戏服":"保存规则"};b.Click+=(s,e)=>{Restart=value;Policy=new JsonObject{["version"]=1,["unarmed"]=Unarmed,["weaponIds"]=new JsonArray(boxes.Where(x=>x.Value.IsChecked==true).Select(x=>(JsonNode?)JsonValue.Create(x.Key)).ToArray())};DialogResult=true;};buttons.Children.Add(b);}var cancel2=new Button{Content="取消"};cancel2.Click+=(s,e)=>Close();buttons.Children.Add(cancel2);UpdateStatus();}
 void UpdateStatus(){status.Text=Unarmed?"空手人机：清空装备并关闭人机载具；保存后重启游戏服应用。":"已禁用 "+boxes.Count(x=>x.Value.IsChecked==true)+" 项；保存后重启游戏服应用。";}
}
